  if (!dir) { console.error("Usage: node generateHar.js <http-log-dir> [output.har]"); process.exit(1); }
  const resolved = path.resolve(dir);
  const out = process.argv[3] ? path.resolve(process.argv[3]) : path.join(resolved, "requests.har");
  const files = await fs.readdir(resolved);
  const reqs = new Map(), resps = new Map(), seqs = new Map(), msgs = new Map(), sseChunks = new Map();
